import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
//import './AboutUs.css'; // We'll add custom styles here

const AboutUs = () => {
  return (
    <div className="about-us container">
      <div className="row align-items-center my-5">
        <div className="col-md-6">
          <h1>We're bringing back <span className="highlight">perspective</span> to news</h1>
          <p className="mt-4">At Searchify, we build technology that improves the way users find reliable and .</p>
          <button className="btn btn-primary mt-4">Learn More</button>
        </div>
        <div className="col-md-6">
          <div className='aboutus-bg'></div>
        </div>
      </div>
    </div>
  );
};

export default AboutUs;
